import{_ as a,o as t,c as i,a8 as n}from"./chunks/framework.DB1tY2mn.js";const h=JSON.parse('{"title":"Agentflow Diagram Config Schema","description":"","frontmatter":{"editLink":"https://github.com/mermaid-js/mermaid/edit/develop/packages/mermaid/src/schemas/config.schema.yaml","head":[["link",{"rel":"canonical","href":"https://mermaid.ai/open-source/config/schema-docs/config-defs-agentflow-diagram-config.html"}]]},"headers":[],"relativePath":"config/schema-docs/config-defs-agentflow-diagram-config.md","filePath":"config/schema-docs/config-defs-agentflow-diagram-config.md"}'),o={name:"config/schema-docs/config-defs-agentflow-diagram-config.md"};function l(s,e,d,r,g,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="agentflow-diagram-config-schema" tabindex="-1">Agentflow Diagram Config Schema <a class="header-anchor" href="#agentflow-diagram-config-schema" aria-label="Permalink to &quot;Agentflow Diagram Config Schema&quot;">​</a></h1><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig</span></span></code></pre></div><p>The object containing configurations specific for the agentflow diagram type.</p><p>Agentflow renders through the shared unified renderer, so it owns the same spacing and padding knobs a flowchart does. They live in their own block so that agentflow can be tuned without moving every flowchart on the page.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Abstract</th><th style="text-align:left;">Extensible</th><th style="text-align:left;">Status</th><th style="text-align:left;">Identifiable</th><th style="text-align:left;">Custom Properties</th><th style="text-align:left;">Additional Properties</th><th style="text-align:left;">Access Restrictions</th><th style="text-align:left;">Defined In</th></tr></thead><tbody><tr><td style="text-align:left;">Can be instantiated</td><td style="text-align:left;">No</td><td style="text-align:left;">Unknown status</td><td style="text-align:left;">No</td><td style="text-align:left;">Forbidden</td><td style="text-align:left;">Allowed</td><td style="text-align:left;">none</td><td style="text-align:left;"><a href="/dochub/mermaid/schemas/config.schema.json" title="open original schema">config.schema.json*</a></td></tr></tbody></table><h2 id="agentflowdiagramconfig-type" tabindex="-1">AgentflowDiagramConfig Type <a class="header-anchor" href="#agentflowdiagramconfig-type" aria-label="Permalink to &quot;AgentflowDiagramConfig Type&quot;">​</a></h2><p><code>object</code> (<a href="./config-defs-agentflow-diagram-config.html">Agentflow Diagram Config</a>)</p><p>all of</p><ul><li><a href="./config-defs-base-diagram-config.html" title="check type definition">Base Diagram Config</a></li></ul><h1 id="agentflowdiagramconfig-properties" tabindex="-1">AgentflowDiagramConfig Properties <a class="header-anchor" href="#agentflowdiagramconfig-properties" aria-label="Permalink to &quot;AgentflowDiagramConfig Properties&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Property</th><th style="text-align:left;">Type</th><th style="text-align:left;">Required</th><th style="text-align:left;">Nullable</th><th style="text-align:left;">Defined by</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="#titletopmargin">titleTopMargin</a></td><td style="text-align:left;"><code>integer</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-defs-agentflow-diagram-config-properties-titletopmargin.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/titleTopMargin">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#diagrampadding">diagramPadding</a></td><td style="text-align:left;"><code>integer</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-defs-agentflow-diagram-config-properties-diagrampadding.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/diagramPadding">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#nodespacing">nodeSpacing</a></td><td style="text-align:left;"><code>integer</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-defs-agentflow-diagram-config-properties-nodespacing.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/nodeSpacing">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#rankspacing">rankSpacing</a></td><td style="text-align:left;"><code>integer</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-defs-agentflow-diagram-config-properties-rankspacing.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/rankSpacing">Mermaid Config</a></td></tr></tbody></table><h2 id="titletopmargin" tabindex="-1">titleTopMargin <a class="header-anchor" href="#titletopmargin" aria-label="Permalink to &quot;titleTopMargin&quot;">​</a></h2><p>Margin top for the text over the diagram</p><p><code>titleTopMargin</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>integer</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-defs-agentflow-diagram-config-properties-titletopmargin.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/titleTopMargin">Mermaid Config</a></p></li></ul><h3 id="titletopmargin-type" tabindex="-1">titleTopMargin Type <a class="header-anchor" href="#titletopmargin-type" aria-label="Permalink to &quot;titleTopMargin Type&quot;">​</a></h3><p><code>integer</code></p><h3 id="titletopmargin-constraints" tabindex="-1">titleTopMargin Constraints <a class="header-anchor" href="#titletopmargin-constraints" aria-label="Permalink to &quot;titleTopMargin Constraints&quot;">​</a></h3><p><strong>minimum</strong>: the value of this number must greater than or equal to: <code>0</code></p><h3 id="titletopmargin-default-value" tabindex="-1">titleTopMargin Default Value <a class="header-anchor" href="#titletopmargin-default-value" aria-label="Permalink to &quot;titleTopMargin Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span></span></code></pre></div><h2 id="diagrampadding" tabindex="-1">diagramPadding <a class="header-anchor" href="#diagrampadding" aria-label="Permalink to &quot;diagramPadding&quot;">​</a></h2><p>The amount of padding around the diagram as a whole so that embedded diagrams have margins, expressed in pixels.</p><p><code>diagramPadding</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>integer</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-defs-agentflow-diagram-config-properties-diagrampadding.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/diagramPadding">Mermaid Config</a></p></li></ul><h3 id="diagrampadding-type" tabindex="-1">diagramPadding Type <a class="header-anchor" href="#diagrampadding-type" aria-label="Permalink to &quot;diagramPadding Type&quot;">​</a></h3><p><code>integer</code></p><h3 id="diagrampadding-constraints" tabindex="-1">diagramPadding Constraints <a class="header-anchor" href="#diagrampadding-constraints" aria-label="Permalink to &quot;diagramPadding Constraints&quot;">​</a></h3><p><strong>minimum</strong>: the value of this number must greater than or equal to: <code>0</code></p><h3 id="diagrampadding-default-value" tabindex="-1">diagramPadding Default Value <a class="header-anchor" href="#diagrampadding-default-value" aria-label="Permalink to &quot;diagramPadding Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span></code></pre></div><h2 id="nodespacing" tabindex="-1">nodeSpacing <a class="header-anchor" href="#nodespacing" aria-label="Permalink to &quot;nodeSpacing&quot;">​</a></h2><p>Defines the spacing between nodes on the same level.</p><p>Pertains to horizontal spacing for TB (top to bottom) or BT (bottom to top) graphs, and the vertical spacing for LR as well as RL graphs.</p><p><code>nodeSpacing</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>integer</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-defs-agentflow-diagram-config-properties-nodespacing.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/nodeSpacing">Mermaid Config</a></p></li></ul><h3 id="nodespacing-type" tabindex="-1">nodeSpacing Type <a class="header-anchor" href="#nodespacing-type" aria-label="Permalink to &quot;nodeSpacing Type&quot;">​</a></h3><p><code>integer</code></p><h3 id="nodespacing-constraints" tabindex="-1">nodeSpacing Constraints <a class="header-anchor" href="#nodespacing-constraints" aria-label="Permalink to &quot;nodeSpacing Constraints&quot;">​</a></h3><p><strong>minimum</strong>: the value of this number must greater than or equal to: <code>0</code></p><h3 id="nodespacing-default-value" tabindex="-1">nodeSpacing Default Value <a class="header-anchor" href="#nodespacing-default-value" aria-label="Permalink to &quot;nodeSpacing Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span></span></code></pre></div><h2 id="rankspacing" tabindex="-1">rankSpacing <a class="header-anchor" href="#rankspacing" aria-label="Permalink to &quot;rankSpacing&quot;">​</a></h2><p>Defines the spacing between nodes on different levels.</p><p>Pertains to vertical spacing for TB (top to bottom) or BT (bottom to top), and the horizontal spacing for LR as well as RL graphs.</p><p><code>rankSpacing</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>integer</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-defs-agentflow-diagram-config-properties-rankspacing.html" title="https://mermaid.js.org/schemas/config.schema.json#/$defs/AgentflowDiagramConfig/properties/rankSpacing">Mermaid Config</a></p></li></ul><h3 id="rankspacing-type" tabindex="-1">rankSpacing Type <a class="header-anchor" href="#rankspacing-type" aria-label="Permalink to &quot;rankSpacing Type&quot;">​</a></h3><p><code>integer</code></p><h3 id="rankspacing-constraints" tabindex="-1">rankSpacing Constraints <a class="header-anchor" href="#rankspacing-constraints" aria-label="Permalink to &quot;rankSpacing Constraints&quot;">​</a></h3><p><strong>minimum</strong>: the value of this number must greater than or equal to: <code>0</code></p><h3 id="rankspacing-default-value" tabindex="-1">rankSpacing Default Value <a class="header-anchor" href="#rankspacing-default-value" aria-label="Permalink to &quot;rankSpacing Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span></span></code></pre></div>',57)])])}const f=a(o,[["render",l]]);export{h as __pageData,f as default};
